     1→// Phase 2: L0NN Biometric Pattern Learning
     2→// 생체 신호 패턴을 신경망으로 학습
     3→
     4→use crate::signals::*;
     5→
     6→/// 신경망 활성화 함수
     7→#[derive(Clone, Debug, PartialEq)]
     8→pub enum Activation {
     9→    Linear,
    10→    ReLU,
    11→    Sigmoid,
    12→    Tanh,
    13→}
    14→
    15→impl Activation {
    16→    pub fn apply(&self, x: f64) -> f64 {
    17→        match self {
    18→            Activation::Linear => x,
    19→            Activation::ReLU => x.max(0.0),
    20→            Activation::Sigmoid => 1.0 / (1.0 + (-x).exp()),
    21→            Activation::Tanh => x.tanh(),
    22→        }
    23→    }
    24→}
    25→
    26→/// 신경망 뉴런
    27→#[derive(Clone, Debug)]
    28→pub struct BiometricNeuron {
    29→    pub weights: Vec<f64>,
    30→    pub bias: f64,
    31→    pub activation: Activation,
    32→    pub learning_rate: f64,
    33→}
    34→
    35→impl BiometricNeuron {
    36→    pub fn new(input_size: usize, activation: Activation, learning_rate: f64) -> Self {
    37→        let mut weights = vec![0.1; input_size];
    38→        // Xavier initialization
    39→        for w in &mut weights {
    40→            *w = (2.0 / (input_size as f64)).sqrt() * (rand::random::<f64>() - 0.5);
    41→        }
    42→
    43→        BiometricNeuron {
    44→            weights,
    45→            bias: 0.0,
    46→            activation,
    47→            learning_rate,
    48→        }
    49→    }
    50→
    51→    pub fn forward(&self, inputs: &[f64]) -> f64 {
    52→        let mut z = self.bias;
    53→        for (i, &input) in inputs.iter().enumerate() {
    54→            if i < self.weights.len() {
    55→                z += self.weights[i] * input;
    56→            }
    57→        }
    58→        self.activation.apply(z)
    59→    }
    60→
    61→    pub fn backward(&mut self, inputs: &[f64], error: f64) {
    62→        for (i, &input) in inputs.iter().enumerate() {
    63→            if i < self.weights.len() {
    64→                self.weights[i] += self.learning_rate * error * input;
    65→            }
    66→        }
    67→        self.bias += self.learning_rate * error;
    68→    }
    69→}
    70→
    71→/// L0NN 신경망 (경량)
    72→#[derive(Clone, Debug)]
    73→pub struct L0NNBiometricLearner {
    74→    pub hidden_neurons: Vec<BiometricNeuron>,  // 8개
    75→    pub output_neuron: BiometricNeuron,        // 1개 (신뢰도)
    76→    pub user_id: String,
    77→    pub training_count: usize,
    78→    pub average_loss: f64,
    79→}
    80→
    81→impl L0NNBiometricLearner {
    82→    pub fn new(user_id: String) -> Self {
    83→        let mut hidden_neurons = Vec::new();
    84→
    85→        // 8개 은닉층 뉴런 (6개 입력: 타이핑 속도, dwell, flight, 터치압, HR, HRV)
    86→        for i in 0..8 {
    87→            let activation = if i % 2 == 0 {
    88→                Activation::ReLU
    89→            } else {
    90→                Activation::Sigmoid
    91→            };
    92→            hidden_neurons.push(BiometricNeuron::new(6, activation, 0.01));
    93→        }
    94→
    95→        // 출력층 뉴런 (8개 입력 → 1개 신뢰도)
    96→        let output_neuron = BiometricNeuron::new(8, Activation::Sigmoid, 0.01);
    97→
    98→        L0NNBiometricLearner {
    99→            hidden_neurons,
   100→            output_neuron,
   101→            user_id,
   102→            training_count: 0,
   103→            average_loss: 0.0,
   104→        }
   105→    }
   106→
   107→    /// 생체 프로필을 신경망 입력으로 변환
   108→    fn profile_to_vector(&self, profile: &BiometricProfile) -> Vec<f64> {
   109→        vec![
   110→            profile.typing_speed / 100.0,          // 정규화
   111→            profile.dwell_time / 100.0,
   112→            profile.flight_time / 200.0,
   113→            profile.touch_pressure,                 // 이미 0.0~1.0
   114→            profile.heart_rate / 200.0,             // 정규화
   115→            profile.heart_rate_variability,         // 이미 0.0~1.0
   116→        ]
   117→    }
   118→
   119→    /// Forward pass
   120→    pub fn forward(&self, profile: &BiometricProfile) -> f64 {
   121→        let inputs = self.profile_to_vector(profile);
   122→
   123→        // Hidden layer
   124→        let mut hidden_outputs = Vec::new();
   125→        for neuron in &self.hidden_neurons {
   126→            hidden_outputs.push(neuron.forward(&inputs));
   127→        }
   128→
   129→        // Output layer
   130→        self.output_neuron.forward(&hidden_outputs)
   131→    }
   132→
   133→    /// 사용자 검증 (학습)
   134→    pub fn learn_user_pattern(&mut self, profile: &BiometricProfile, target: f64) -> f64 {
   135→        let inputs = self.profile_to_vector(profile);
   136→
   137→        // Forward pass
   138→        let mut hidden_outputs = Vec::new();
   139→        for neuron in &self.hidden_neurons {
   140→            hidden_outputs.push(neuron.forward(&inputs));
   141→        }
   142→
   143→        let prediction = self.output_neuron.forward(&hidden_outputs);
   144→
   145→        // Loss 계산 (Mean Squared Error)
   146→        let loss = (target - prediction).powi(2);
   147→
   148→        // Backward pass
   149→        let output_error = (prediction - target) * prediction * (1.0 - prediction);
   150→        self.output_neuron.backward(&hidden_outputs, output_error);
   151→
   152→        // Hidden layer backward
   153→        for (i, neuron) in self.hidden_neurons.iter_mut().enumerate() {
   154→            let hidden_error = output_error * self.output_neuron.weights[i];
   155→            neuron.backward(&inputs, hidden_error);
   156→        }
   157→
   158→        // 통계 업데이트
   159→        self.training_count += 1;
   160→        self.average_loss = (self.average_loss * (self.training_count - 1) as f64 + loss)
   161→            / self.training_count as f64;
   162→
   163→        loss
   164→    }
   165→
   166→    /// 사용자 프로필 학습 (여러 샘플)
   167→    pub fn train_on_profiles(&mut self, profiles: &[BiometricProfile], epochs: usize) {
   168→        for _ in 0..epochs {
   169→            for profile in profiles {
   170→                // 사용자 자신의 패턴이므로 target = 1.0 (본인)
   171→                self.learn_user_pattern(profile, 1.0);
   172→            }
   173→        }
   174→    }
   175→
   176→    /// 신뢰도 점수 계산 (0.0~1.0)
   177→    pub fn confidence_score(&self, profile: &BiometricProfile) -> f64 {
   178→        self.forward(profile)
   179→    }
   180→
   181→    /// 사용자 인증 (임계값 기반)
   182→    pub fn authenticate(&self, profile: &BiometricProfile, threshold: f64) -> bool {
   183→        self.confidence_score(profile) >= threshold
   184→    }
   185→
   186→    /// 모델 정확도 평가
   187→    pub fn evaluate(&self, test_profiles: &[BiometricProfile], labels: &[f64]) -> ModelMetrics {
   188→        let mut correct = 0;
   189→        let mut total_error = 0.0;
   190→
   191→        for (profile, &label) in test_profiles.iter().zip(labels.iter()) {
   192→            let score = self.confidence_score(profile);
   193→            let error = (score - label).abs();
   194→            total_error += error;
   195→
   196→            // 임계값 0.5로 판단
   197→            let prediction = if score >= 0.5 { 1.0 } else { 0.0 };
   198→            if (prediction - label).abs() < 0.01 {
   199→                correct += 1;
   200→            }
   201→        }
   202→
   203→        let accuracy = correct as f64 / test_profiles.len() as f64;
   204→        let avg_error = total_error / test_profiles.len() as f64;
   205→
   206→        ModelMetrics {
   207→            accuracy,
   208→            avg_error,
   209→            total_correct: correct,
   210→            total_samples: test_profiles.len(),
   211→        }
   212→    }
   213→
   214→    /// 사용자 모델 저장 (직렬화)
   215→    pub fn serialize(&self) -> UserBiometricModel {
   216→        UserBiometricModel {
   217→            user_id: self.user_id.clone(),
   218→            hidden_weights: self.hidden_neurons
   219→                .iter()
   220→                .map(|n| n.weights.clone())
   221→                .collect(),
   222→            output_weights: self.output_neuron.weights.clone(),
   223→            training_count: self.training_count,
   224→            average_loss: self.average_loss,
   225→        }
   226→    }
   227→}
   228→
   229→/// 사용자 생체 모델 (저장용)
   230→#[derive(Clone, Debug)]
   231→pub struct UserBiometricModel {
   232→    pub user_id: String,
   233→    pub hidden_weights: Vec<Vec<f64>>,
   234→    pub output_weights: Vec<f64>,
   235→    pub training_count: usize,
   236→    pub average_loss: f64,
   237→}
   238→
   239→/// 모델 평가 지표
   240→#[derive(Clone, Debug)]
   241→pub struct ModelMetrics {
   242→    pub accuracy: f64,
   243→    pub avg_error: f64,
   244→    pub total_correct: usize,
   245→    pub total_samples: usize,
   246→}
