     1→// Phase 3: Authentication Engine
     2→// L0NN 신경망 + 스푸핑 탐지를 통합한 인증 시스템
     3→
     4→use crate::learning::*;
     5→use crate::signals::*;
     6→use super::metrics::*;
     7→use super::spoofing_detector::*;
     8→
     9→/// 인증 결정
    10→#[derive(Clone, Debug, PartialEq)]
    11→pub enum AuthenticationDecision {
    12→    Accept,                    // 본인으로 인증
    13→    Reject,                    // 타인으로 거부
    14→    RejectHighRisk,           // 스푸핑 의심으로 거부
    15→}
    16→
    17→/// 인증 상세 결과
    18→#[derive(Clone, Debug)]
    19→pub struct AuthenticationDetails {
    20→    pub decision: AuthenticationDecision,
    21→    pub confidence_score: f64,        // 신경망 신뢰도 [0, 1]
    22→    pub spoofing_risk_level: SpoofingRisk,  // 스푸핑 위험
    23→    pub liveness_score: f64,          // 신호 생생함 [0, 1]
    24→    pub final_score: f64,             // 최종 인증 점수 [0, 1]
    25→    pub reasoning: String,            // 판정 이유
    26→}
    27→
    28→/// 인증 엔진
    29→#[derive(Clone, Debug)]
    30→pub struct AuthenticationEngine {
    31→    pub learner: L0NNBiometricLearner,
    32→    pub spoofing_detector: SpoofingDetector,
    33→    pub confidence_threshold: f64,     // 신경망 임계값
    34→    pub spoofing_threshold: f64,       // 스푸핑 거부 임계값
    35→    pub authentication_attempts: Vec<AuthenticationAttempt>,
    36→    pub total_authentications: usize,
    37→}
    38→
    39→impl AuthenticationEngine {
    40→    pub fn new(user_id: String) -> Self {
    41→        AuthenticationEngine {
    42→            learner: L0NNBiometricLearner::new(user_id),
    43→            spoofing_detector: SpoofingDetector::new(),
    44→            confidence_threshold: 0.5,
    45→            spoofing_threshold: 0.5,  // 신뢰도 < 0.5 = 의심
    46→            authentication_attempts: Vec::new(),
    47→            total_authentications: 0,
    48→        }
    49→    }
    50→
    51→    /// 사용자 등록: 본인의 생체 신호로 신경망 학습
    52→    pub fn enroll(
    53→        &mut self,
    54→        keystroke_signals: &[KeystrokeSignal],
    55→        touch_signals: &[TouchSignal],
    56→        hr_signals: &[HeartRateSignal],
    57→    ) {
    58→        let profile = self.create_biometric_profile(keystroke_signals, touch_signals, hr_signals);
    59→
    60→        // 여러 번 학습하여 패턴 정착
    61→        for _ in 0..10 {
    62→            self.learner.learn_user_pattern(&profile, 1.0);
    63→        }
    64→    }
    65→
    66→    /// 인증 시도
    67→    pub fn authenticate(
    68→        &mut self,
    69→        keystroke_signals: &[KeystrokeSignal],
    70→        touch_signals: &[TouchSignal],
    71→        hr_signals: &[HeartRateSignal],
    72→        is_genuine: bool,  // 테스트용: 실제로 본인인지
    73→    ) -> AuthenticationDetails {
    74→        self.total_authentications += 1;
    75→
    76→        let profile = self.create_biometric_profile(keystroke_signals, touch_signals, hr_signals);
    77→
    78→        // 1. 신경망 신뢰도 계산
    79→        let confidence_score = self.learner.confidence_score(&profile);
    80→
    81→        // 2. 스푸핑 탐지
    82→        let spoofing_result = self.spoofing_detector.detect_spoofing(
    83→            keystroke_signals,
    84→            touch_signals,
    85→            hr_signals,
    86→        );
    87→
    88→        // 3. 최종 점수 계산
    89→        // final_score = confidence * (1 - spoofing_risk)
    90→        let spoofing_confidence = spoofing_result.overall_confidence;
    91→        let final_score = confidence_score * spoofing_confidence;
    92→
    93→        // 4. 인증 결정
    94→        let decision = if spoofing_result.risk_level == SpoofingRisk::High
    95→            || spoofing_result.risk_level == SpoofingRisk::Critical
    96→        {
    97→            AuthenticationDecision::RejectHighRisk
    98→        } else if final_score >= self.confidence_threshold {
    99→            AuthenticationDecision::Accept
   100→        } else {
   101→            AuthenticationDecision::Reject
   102→        };
   103→
   104→        // 5. 판정 이유 작성
   105→        let reasoning = match decision {
   106→            AuthenticationDecision::Accept => format!(
   107→                "Biometric confidence {:.1}% + liveness {:.1}% = ACCEPT",
   108→                confidence_score * 100.0,
   109→                spoofing_confidence * 100.0
   110→            ),
   111→            AuthenticationDecision::Reject => format!(
   112→                "Biometric confidence {:.1}% below threshold {:.1}% = REJECT",
   113→                confidence_score * 100.0,
   114→                self.confidence_threshold * 100.0
   115→            ),
   116→            AuthenticationDecision::RejectHighRisk => format!(
   117→                "High spoofing risk: {:?} (liveness {:.1}%) = REJECT",
   118→                spoofing_result.risk_level,
   119→                spoofing_confidence * 100.0
   120→            ),
   121→        };
   122→
   123→        // 6. 인증 시도 기록
   124→        let predicted_result = match decision {
   125→            AuthenticationDecision::Accept => AuthenticationResult::Accept,
   126→            _ => AuthenticationResult::Reject,
   127→        };
   128→
   129→        self.authentication_attempts.push(AuthenticationAttempt {
   130→            is_genuine,
   131→            predicted_result,
   132→            confidence_score,
   133→            timestamp: 0,
   134→        });
   135→
   136→        AuthenticationDetails {
   137→            decision,
   138→            confidence_score,
   139→            spoofing_risk_level: spoofing_result.risk_level,
   140→            liveness_score: spoofing_result.overall_confidence,
   141→            final_score,
   142→            reasoning,
   143→        }
   144→    }
   145→
   146→    /// 생체 신호로부터 프로필 생성
   147→    fn create_biometric_profile(
   148→        &self,
   149→        keystroke_signals: &[KeystrokeSignal],
   150→        touch_signals: &[TouchSignal],
   151→        hr_signals: &[HeartRateSignal],
   152→    ) -> BiometricProfile {
   153→        // 임시 collector를 만들어 프로필 생성
   154→        let mut collector = BiometricCollector::new(1000);
   155→
   156→        for ks in keystroke_signals {
   157→            collector.record_keystroke(
   158→                ks.key,
   159→                ks.timestamp,
   160→                ks.press_duration,
   161→                ks.flight_time,
   162→                ks.pressure,
   163→            );
   164→        }
   165→
   166→        for ts in touch_signals {
   167→            collector.record_touch(ts.x, ts.y, ts.pressure, ts.timestamp, ts.duration);
   168→        }
   169→
   170→        for hrs in hr_signals {
   171→            collector.record_heartrate(hrs.bpm, hrs.timestamp, hrs.variability, hrs.confidence);
   172→        }
   173→
   174→        collector.biometric_profile()
   175→    }
   176→
   177→    /// 현재까지의 인증 성능 메트릭
   178→    pub fn get_metrics(&self) -> AuthenticationMetrics {
   179→        AuthenticationMetrics::from_attempts(&self.authentication_attempts)
   180→    }
   181→
   182→    /// FAR 달성 상황 (Rule: FAR < 0.0001%)
   183→    pub fn far_compliance(&self) -> bool {
   184→        let metrics = self.get_metrics();
   185→        metrics.meets_far_requirement()
   186→    }
   187→
   188→    /// FRR 달성 상황 (Rule: FRR < 1%)
   189→    pub fn frr_compliance(&self) -> bool {
   190→        let metrics = self.get_metrics();
   191→        metrics.meets_frr_requirement()
   192→    }
   193→
   194→    /// 모든 무관용 규칙 준수
   195→    pub fn all_rules_passed(&self) -> bool {
   196→        let metrics = self.get_metrics();
   197→        metrics.meets_all_requirements()
   198→    }
   199→}
