     1→// Phase 3: Authentication Metrics
     2→// FAR (False Acceptance Rate), FRR (False Rejection Rate), EER (Equal Error Rate)
     3→
     4→/// 인증 결과 타입
     5→#[derive(Clone, Debug, PartialEq)]
     6→pub enum AuthenticationResult {
     7→    Accept,      // 본인으로 판단
     8→    Reject,      // 타인으로 판단
     9→}
    10→
    11→/// 단일 인증 시도 기록
    12→#[derive(Clone, Debug)]
    13→pub struct AuthenticationAttempt {
    14→    pub is_genuine: bool,           // 실제로 본인인지 (테스트에서만 알려짐)
    15→    pub predicted_result: AuthenticationResult,  // 예측 결과
    16→    pub confidence_score: f64,      // 신뢰도 [0, 1]
    17→    pub timestamp: u64,
    18→}
    19→
    20→/// 인증 성능 지표
    21→#[derive(Clone, Debug)]
    22→pub struct AuthenticationMetrics {
    23→    pub false_acceptance_rate: f64,  // FAR: 타인을 본인으로 잘못 인증
    24→    pub false_rejection_rate: f64,   // FRR: 본인을 타인으로 잘못 거부
    25→    pub equal_error_rate: f64,       // EER: FAR = FRR인 지점의 에러율
    26→    pub genuine_accept_rate: f64,    // GAR: 본인을 올바르게 인증한 비율
    27→    pub impostor_reject_rate: f64,   // IRR: 타인을 올바르게 거부한 비율
    28→    pub total_genuine_attempts: usize,
    29→    pub total_impostor_attempts: usize,
    30→    pub total_correct: usize,
    31→    pub total_attempts: usize,
    32→}
    33→
    34→impl AuthenticationMetrics {
    35→    pub fn new() -> Self {
    36→        AuthenticationMetrics {
    37→            false_acceptance_rate: 0.0,
    38→            false_rejection_rate: 0.0,
    39→            equal_error_rate: 0.0,
    40→            genuine_accept_rate: 0.0,
    41→            impostor_reject_rate: 0.0,
    42→            total_genuine_attempts: 0,
    43→            total_impostor_attempts: 0,
    44→            total_correct: 0,
    45→            total_attempts: 0,
    46→        }
    47→    }
    48→
    49→    /// 인증 시도 기록으로부터 메트릭스 계산
    50→    pub fn from_attempts(attempts: &[AuthenticationAttempt]) -> Self {
    51→        let mut metrics = Self::new();
    52→
    53→        let mut genuine_accepted = 0;
    54→        let mut genuine_rejected = 0;
    55→        let mut impostor_accepted = 0;
    56→        let mut impostor_rejected = 0;
    57→
    58→        for attempt in attempts {
    59→            metrics.total_attempts += 1;
    60→
    61→            if attempt.is_genuine {
    62→                metrics.total_genuine_attempts += 1;
    63→                if attempt.predicted_result == AuthenticationResult::Accept {
    64→                    genuine_accepted += 1;
    65→                    metrics.total_correct += 1;
    66→                } else {
    67→                    genuine_rejected += 1;
    68→                }
    69→            } else {
    70→                metrics.total_impostor_attempts += 1;
    71→                if attempt.predicted_result == AuthenticationResult::Accept {
    72→                    impostor_accepted += 1;
    73→                } else {
    74→                    impostor_rejected += 1;
    75→                    metrics.total_correct += 1;
    76→                }
    77→            }
    78→        }
    79→
    80→        // FAR = 타인이 본인으로 인증된 비율
    81→        if metrics.total_impostor_attempts > 0 {
    82→            metrics.false_acceptance_rate = impostor_accepted as f64
    83→                / metrics.total_impostor_attempts as f64;
    84→        }
    85→
    86→        // FRR = 본인이 타인으로 거부된 비율
    87→        if metrics.total_genuine_attempts > 0 {
    88→            metrics.false_rejection_rate = genuine_rejected as f64
    89→                / metrics.total_genuine_attempts as f64;
    90→        }
    91→
    92→        // GAR = 본인을 올바르게 인증한 비율
    93→        if metrics.total_genuine_attempts > 0 {
    94→            metrics.genuine_accept_rate = genuine_accepted as f64
    95→                / metrics.total_genuine_attempts as f64;
    96→        }
    97→
    98→        // IRR = 타인을 올바르게 거부한 비율
    99→        if metrics.total_impostor_attempts > 0 {
   100→            metrics.impostor_reject_rate = impostor_rejected as f64
   101→                / metrics.total_impostor_attempts as f64;
   102→        }
   103→
   104→        // EER ≈ (FAR + FRR) / 2
   105→        metrics.equal_error_rate =
   106→            (metrics.false_acceptance_rate + metrics.false_rejection_rate) / 2.0;
   107→
   108→        metrics
   109→    }
   110→
   111→    /// FAR을 백만분의 몇으로 표현 (예: 0.0001% = 1 in 1,000,000)
   112→    pub fn far_in_ppm(&self) -> f64 {
   113→        self.false_acceptance_rate * 1_000_000.0
   114→    }
   115→
   116→    /// FRR을 백분율로 표현
   117→    pub fn frr_percentage(&self) -> f64 {
   118→        self.false_rejection_rate * 100.0
   119→    }
   120→
   121→    /// 인증 정확도
   122→    pub fn accuracy(&self) -> f64 {
   123→        if self.total_attempts == 0 {
   124→            return 0.0;
   125→        }
   126→        self.total_correct as f64 / self.total_attempts as f64
   127→    }
   128→
   129→    /// 무관용 규칙 검증
   130→    /// Rule: FAR < 0.0001% (1 in 1,000,000)
   131→    pub fn meets_far_requirement(&self) -> bool {
   132→        self.false_acceptance_rate < 0.000001  // 0.0001% = 0.000001
   133→    }
   134→
   135→    /// 무관용 규칙 검증
   136→    /// Rule: FRR < 1%
   137→    pub fn meets_frr_requirement(&self) -> bool {
   138→        self.false_rejection_rate < 0.01  // 1% = 0.01
   139→    }
   140→
   141→    /// 두 무관용 규칙 모두 충족
   142→    pub fn meets_all_requirements(&self) -> bool {
   143→        self.meets_far_requirement() && self.meets_frr_requirement()
   144→    }
   145→}
