     4→use crate::signals::*;
     5→
     6→/// 스푸핑 위험 수준
     7→#[derive(Clone, Debug, PartialEq)]
     8→pub enum SpoofingRisk {
     9→    Safe,       // 안전 (정상 신호)
    10→    Low,        // 낮음 (약간의 이상)
    11→    Medium,     // 중간 (의심 신호)
    12→    High,       // 높음 (강한 의심)
    13→    Critical,   // 위험 (공격 가능성 높음)
    14→}
    15→
    16→/// 스푸핑 탐지 결과
    17→#[derive(Clone, Debug)]
    18→pub struct SpoofingDetectionResult {
    19→    pub risk_level: SpoofingRisk,
    20→    pub liveness_score: f64,        // [0, 1]: 1 = 실시간 신호, 0 = 녹음/복제
    21→    pub plausibility_score: f64,    // [0, 1]: 1 = 생리적으로 타당함
    22→    pub overall_confidence: f64,    // [0, 1]: 공격 아닐 확률
    23→    pub reasons: Vec<String>,       // 의심 이유 설명
    24→}
    25→
    26→/// 스푸핑 탐지기
    27→#[derive(Clone, Debug)]
    28→pub struct SpoofingDetector {
    29→    pub liveness_threshold: f64,     // 기본값: 0.3 (0.3 이하 = 의심)
    30→    pub plausibility_threshold: f64, // 기본값: 0.4 (0.4 이하 = 의심)
    31→}
    32→
    33→impl SpoofingDetector {
    34→    pub fn new() -> Self {
    35→        SpoofingDetector {
    36→            liveness_threshold: 0.3,
    37→            plausibility_threshold: 0.4,
    38→        }
    39→    }
    40→
    41→    /// 키스트로크 동역학의 실시간성 검사
    42→    /// 타이핑이 자연스럽게 변하는지 확인
    43→    fn keystroke_liveness_check(&self, keystroke_signals: &[KeystrokeSignal]) -> f64 {
    44→        if keystroke_signals.len() < 3 {
    45→            return 0.5;  // 데이터 부족
    46→        }
    47→
    48→        // 시간차 변화율 분석 (flight_time의 표준편차)
    49→        let flight_times: Vec<u64> = keystroke_signals
    50→            .iter()
    51→            .map(|k| k.flight_time)
    52→            .collect();
    53→
    54→        if flight_times.is_empty() {
    55→            return 0.5;
    56→        }
    57→
    58→        let mean: f64 = flight_times.iter().map(|&t| t as f64).sum::<f64>()
    59→            / flight_times.len() as f64;
    60→
    61→        let variance: f64 = flight_times
    62→            .iter()
    63→            .map(|&t| {
    64→                let diff = t as f64 - mean;
    65→                diff * diff
    66→            })
    67→            .sum::<f64>()
    68→            / flight_times.len() as f64;
    69→
    70→        let std_dev = variance.sqrt();
    71→
    72→        // 표준편차가 크면 = 자연스러운 타이핑 = 높은 생생함
    73→        // 표준편차가 작으면 = 기계적 타이핑 = 의심 신호
    74→        let liveness = (std_dev / (mean + 1.0)).min(1.0);  // [0, 1]
    75→
    76→        // 압력의 변화도 확인
    77→        let pressures: Vec<f64> = keystroke_signals
    78→            .iter()
    79→            .map(|k| k.pressure)
    80→            .collect();
    81→
    82→        if !pressures.is_empty() {
    83→            let pressure_mean = pressures.iter().sum::<f64>() / pressures.len() as f64;
    84→            let pressure_variance: f64 = pressures
    85→                .iter()
    86→                .map(|&p| {
    87→                    let diff = p - pressure_mean;
    88→                    diff * diff
    89→                })
    90→                .sum::<f64>()
    91→                / pressures.len() as f64;
    92→
    93→            let pressure_std_dev = pressure_variance.sqrt();
    94→            let pressure_liveness = (pressure_std_dev * 2.0).min(1.0);
    95→
    96→            return (liveness + pressure_liveness) / 2.0;
    97→        }
    98→
    99→        liveness
   100→    }
   101→
   102→    /// 심박수의 생리적 타당성 검사
   103→    fn heart_rate_plausibility(&self, hr_signals: &[HeartRateSignal]) -> f64 {
   104→        if hr_signals.is_empty() {
   105→            return 0.5;
   106→        }
   107→
   108→        let mut plausibility = 1.0;
   109→
   110→        // 1. 심박수가 생리적 범위인지 확인 (40~200 BPM)
   111→        for signal in hr_signals {
   112→            if signal.bpm < 40.0 || signal.bpm > 200.0 {
   113→                plausibility -= 0.3;
   114→            }
   115→        }
   116→
   117→        // 2. 심박수가 급격히 변하지 않는지 확인
   118→        if hr_signals.len() >= 2 {
   119→            for i in 1..hr_signals.len() {
   120→                let bpm_change = (hr_signals[i].bpm - hr_signals[i - 1].bpm).abs();
   121→                // 100ms 단위로 BPM이 10 이상 변하면 의심 (실제로 불가능)
   122→                if bpm_change > 10.0 {
   123→                    plausibility -= 0.1;
   124→                }
   125→            }
   126→        }
   127→
   128→        // 3. HRV (심박수 변이도)가 합리적인 범위인지 확인
   129→        let avg_hrv: f64 = hr_signals.iter().map(|s| s.variability).sum::<f64>()
   130→            / hr_signals.len() as f64;
   131→        if avg_hrv < 0.2 || avg_hrv > 0.9 {
   132→            plausibility -= 0.2;  // HRV가 너무 작거나 크면 의심
   133→        }
   134→
   135→        plausibility.max(0.0).min(1.0)
   136→    }
   137→
   138→    /// 터치 압력의 일관성 검사
   139→    fn touch_pressure_consistency(&self, touch_signals: &[TouchSignal]) -> f64 {
   140→        if touch_signals.len() < 2 {
   141→            return 0.5;
   142→        }
   143→
   144→        let pressures: Vec<f64> = touch_signals.iter().map(|t| t.pressure).collect();
   145→        let mean: f64 = pressures.iter().sum::<f64>() / pressures.len() as f64;
   146→
   147→        // 표준편차가 너무 크면 = 일관성 없음 = 의심
   148→        let variance: f64 = pressures
   149→            .iter()
   150→            .map(|&p| {
   151→                let diff = p - mean;
   152→                diff * diff
   153→            })
   154→            .sum::<f64>()
   155→            / pressures.len() as f64;
   156→
   157→        let std_dev = variance.sqrt();
   158→
   159→        // CV (Coefficient of Variation) = std_dev / mean
   160→        let cv = if mean > 0.0 { std_dev / mean } else { 0.5 };
   161→
   162→        // CV가 작을수록 일관성 있음
   163→        (1.0 - cv).max(0.0).min(1.0)
   164→    }
   165→
   166→    /// 전체 스푸핑 탐지 분석
   167→    pub fn detect_spoofing(
   168→        &self,
   169→        keystroke_signals: &[KeystrokeSignal],
   170→        touch_signals: &[TouchSignal],
   171→        hr_signals: &[HeartRateSignal],
   172→    ) -> SpoofingDetectionResult {
   173→        let liveness_score = self.keystroke_liveness_check(keystroke_signals);
   174→        let plausibility_score = self.heart_rate_plausibility(hr_signals);
   175→        let consistency_score = self.touch_pressure_consistency(touch_signals);
   176→
   177→        // 종합 신뢰도 = (생생함 + 타당성 + 일관성) / 3
   178→        let overall_confidence = (liveness_score + plausibility_score + consistency_score) / 3.0;
   179→
   180→        let mut reasons = Vec::new();
   181→
   182→        // 위험 수준 결정
   183→        let risk_level = if liveness_score < self.liveness_threshold {
   184→            reasons.push(format!(
   185→                "Low keystroke liveness ({})",
   186→                (liveness_score * 100.0) as i32
   187→            ));
   188→            SpoofingRisk::High
   189→        } else if plausibility_score < self.plausibility_threshold {
   190→            reasons.push(format!(
   191→                "Implausible heart rate pattern ({})",
   192→                (plausibility_score * 100.0) as i32
   193→            ));
   194→            SpoofingRisk::High
   195→        } else if consistency_score < 0.3 {
   196→            reasons.push(format!(
   197→                "Inconsistent touch pressure ({})",
   198→                (consistency_score * 100.0) as i32
   199→            ));
   200→            SpoofingRisk::Medium
   201→        } else if overall_confidence < 0.5 {
   202→            reasons.push("Multiple minor anomalies detected".to_string());
   203→            SpoofingRisk::Medium
   204→        } else if overall_confidence < 0.7 {
   205→            reasons.push("Slightly unusual biometric pattern".to_string());
   206→            SpoofingRisk::Low
   207→        } else {
   208→            reasons.push("Biometric signals appear natural".to_string());
   209→            SpoofingRisk::Safe
   210→        };
   211→
   212→        SpoofingDetectionResult {
   213→            risk_level,
   214→            liveness_score,
   215→            plausibility_score: (plausibility_score + consistency_score) / 2.0,
   216→            overall_confidence,
   217→            reasons,
   218→        }
   219→    }
   220→}
