    11→/// 동적 키 생성 결과
    12→#[derive(Clone, Debug)]
    13→pub struct DynamicKeyResult {
    14→    pub generation_key: Vec<u8>,              // 생성된 키 (32 bytes)
    15→    pub key_id: String,                        // 키 식별자
    16→    pub entropy_bits: f64,                     // 엔트로피 (비트)
    17→    pub is_valid: bool,                        // 엔트로피 >= 128비트
    18→    pub timestamp: u64,
    19→    pub metadata: String,
    20→}
    21→
    22→/// 동적 키 생성 엔진
    23→#[derive(Clone, Debug)]
    24→pub struct DynamicKeyGenerator {
    25→    pub user_id: String,
    26→    pub master_secret: Vec<u8>,               // 사용자의 고정 비밀 (등록 시 생성)
    27→}
    28→
    29→impl DynamicKeyGenerator {
    30→    pub fn new(user_id: String) -> Self {
    31→        // 마스터 시크릿 생성 (user_id 기반)
    32→        let master_secret = hmac_sha256(user_id.as_bytes(), b"master_secret").bytes.to_vec();
    33→
    34→        DynamicKeyGenerator {
    35→            user_id,
    36→            master_secret,
    37→        }
    38→    }
    39→
    40→    /// 인증 성공 시 동적 키 생성
    41→    pub fn generate_key_on_authentication(
    42→        &self,
    43→        auth_decision: &AuthenticationDecision,
    44→        confidence_score: f64,
    45→        model_fingerprint: &str,  // 신경망 모델의 해시
    46→    ) -> Result<DynamicKeyResult, String> {
    47→        // Step 1: 인증 실패 시 거부
    48→        if *auth_decision != AuthenticationDecision::Accept {
    49→            return Err("Authentication failed - cannot generate key".to_string());
    50→        }
    51→
    52→        // Step 2: 신뢰도 검증 (최소 0.5)
    53→        if confidence_score < 0.5 {
    54→            return Err("Confidence score too low for key generation".to_string());
    55→        }
    56→
    57→        // Step 3: 키 유도
    58→        let params = KeyDerivationParams::new();
    59→        let derived = derive_key_from_biometric(
    60→            &self.user_id,
    61→            confidence_score,
    62→            model_fingerprint,
    63→            &params,
    64→        );
    65→
    66→        // Step 4: 마스터 시크릿과 결합
    67→        let combined = [self.master_secret.clone(), derived.key.clone()].concat();
    68→        let final_key = hmac_sha256(&combined, b"dynamic_key").bytes.to_vec();
    69→
    70→        // Step 5: 엔트로피 검증
    71→        let analysis = analyze_entropy(&final_key);
    72→
    73→        // Step 6: 키 ID 생성
    74→        let key_id_hash = sha256(
    75→            format!(
    76→                "{}:{}:{}",
    77→                self.user_id,
    78→                (confidence_score * 1_000_000.0) as u64,
    79→                model_fingerprint
    80→            )
    81→            .as_bytes(),
    82→        );
    83→        let key_id = key_id_hash.to_hex()[..16].to_string();
    84→
    85→        Ok(DynamicKeyResult {
    86→            generation_key: final_key,
    87→            key_id,
    88→            entropy_bits: analysis.entropy_bits,
    89→            is_valid: analysis.meets_nist_requirement(),
    90→            timestamp: 0,
    91→            metadata: format!(
    92→                "user={}, confidence={:.2}%, entropy={:.1}bits, model={}",
    93→                self.user_id,
    94→                confidence_score * 100.0,
    95→                analysis.entropy_bits,
    96→                &model_fingerprint[..8.min(model_fingerprint.len())]
    97→            ),
    98→        })
    99→    }
   100→
   101→    /// 템플릿 암호화 (생성된 키로)
   102→    pub fn encrypt_user_template(
   103→        &self,
   104→        template: &PlaintextTemplate,
   105→        auth_decision: &AuthenticationDecision,
   106→        confidence_score: f64,
   107→        model_fingerprint: &str,
   108→    ) -> Result<EncryptedTemplate, String> {
   109→        // 동적 키 생성
   110→        let key_result = self.generate_key_on_authentication(auth_decision, confidence_score, model_fingerprint)?;
   111→
   112→        if !key_result.is_valid {
   113→            return Err("Generated key does not meet entropy requirements".to_string());
   114→        }
   115→
   116→        // 템플릿 암호화
   117→        Ok(encrypt_template(template, &key_result.generation_key))
   118→    }
   119→
   120→    /// 템플릿 복호화 (재인증 후)
   121→    pub fn decrypt_user_template(
   122→        &self,
   123→        encrypted: &EncryptedTemplate,
   124→        auth_decision: &AuthenticationDecision,
   125→        confidence_score: f64,
   126→        model_fingerprint: &str,
   127→    ) -> Result<PlaintextTemplate, String> {
   128→        // 동적 키 생성 (동일한 조건)
   129→        let key_result = self.generate_key_on_authentication(auth_decision, confidence_score, model_fingerprint)?;
   130→
   131→        // 템플릿 복호화
   132→        decrypt_template(encrypted, &key_result.generation_key)
   133→    }
   134→
   135→    /// 여러 하위 키 생성 (다양한 용도)
   136→    pub fn derive_subkeys_for_purposes(
   137→        &self,
   138→        auth_decision: &AuthenticationDecision,
   139→        confidence_score: f64,
   140→        model_fingerprint: &str,
   141→        purposes: &[&str],  // ["encryption", "authentication", "integrity", ...]
   142→    ) -> Result<Vec<(String, Vec<u8>)>, String> {
   143→        let key_result = self.generate_key_on_authentication(auth_decision, confidence_score, model_fingerprint)?;
   144→
   145→        let subkeys = derive_multiple_keys(&key_result.generation_key, purposes.len(), 32);
   146→
   147→        let result = purposes
   148→            .iter()
   149→            .zip(subkeys)
   150→            .map(|(purpose, key)| (purpose.to_string(), key))
   151→            .collect();
   152→
   153→        Ok(result)
   154→    }
   155→
   156→    /// 무관용 규칙: 동일한 입력 → 동일한 키
   157→    pub fn verify_key_determinism(
   158→        &self,
   159→        auth_decision: &AuthenticationDecision,
   160→        confidence_score: f64,
   161→        model_fingerprint: &str,
   162→    ) -> Result<bool, String> {
   163→        let key1 = self.generate_key_on_authentication(auth_decision, confidence_score, model_fingerprint)?;
   164→        let key2 = self.generate_key_on_authentication(auth_decision, confidence_score, model_fingerprint)?;
   165→
   166→        Ok(key1.generation_key == key2.generation_key)
   167→    }
   168→}
