     5→
     6→/// 키 유도 파라미터
     7→#[derive(Clone, Debug)]
     8→pub struct KeyDerivationParams {
     9→    pub iterations: usize,    // PBKDF2 반복 횟수 (기본: 2000)
    10→    pub salt_length: usize,   // 솔트 길이 (기본: 16)
    11→    pub output_length: usize, // 출력 키 길이 (기본: 32 = 256비트)
    12→}
    13→
    14→impl KeyDerivationParams {
    15→    pub fn new() -> Self {
    16→        KeyDerivationParams {
    17→            iterations: 2000,     // NIST 권장: 최소 1000-2000
    18→            salt_length: 16,      // 16바이트 = 128비트
    19→            output_length: 32,    // 32바이트 = 256비트
    20→        }
    21→    }
    22→
    23→    pub fn with_iterations(mut self, iterations: usize) -> Self {
    24→        self.iterations = iterations;
    25→        self
    26→    }
    27→
    28→    pub fn with_output_length(mut self, length: usize) -> Self {
    29→        self.output_length = length;
    30→        self
    31→    }
    32→}
    33→
    34→/// 키 유도 결과
    35→#[derive(Clone, Debug)]
    36→pub struct DerivedKey {
    37→    pub key: Vec<u8>,
    38→    pub salt: Vec<u8>,
    39→    pub iterations: usize,
    40→}
    41→
    42→impl DerivedKey {
    43→    /// 키를 16진수 문자열로 표현
    44→    pub fn to_hex(&self) -> String {
    45→        bytes_to_hex(&self.key)
    46→    }
    47→
    48→    /// 검증용 정보
    49→    pub fn metadata(&self) -> String {
    50→        format!(
    51→            "key_len={}, salt_len={}, iterations={}",
    52→            self.key.len(),
    53→            self.salt.len(),
    54→            self.iterations
    55→        )
    56→    }
    57→}
    58→
    59→/// PBKDF2-like 키 유도 함수
    60→/// 생체 신호 + 임계값을 이용한 결정적 키 생성
    61→pub fn derive_key_from_biometric(
    62→    user_id: &str,
    63→    confidence_score: f64,
    64→    fingerprint: &str,  // 신경망 모델의 해시
    65→    params: &KeyDerivationParams,
    66→) -> DerivedKey {
    67→    // Step 1: 솔트 생성 (user_id 기반)
    68→    let salt_base = format!("{}:{}", user_id, fingerprint);
    69→    let salt_hash = sha256(salt_base.as_bytes());
    70→    let salt = salt_hash.bytes[..params.salt_length].to_vec();
    71→
    72→    // Step 2: 비밀 입력값 생성
    73→    // password = user_id + confidence_score + fingerprint
    74→    let password = format!(
    75→        "{}:{}:{}",
    76→        user_id,
    77→        (confidence_score * 1_000_000.0) as u64,
    78→        fingerprint
    79→    );
    80→
    81→    // Step 3: PBKDF2-like 반복
    82→    let mut derived = hmac_sha256(password.as_bytes(), &salt);
    83→
    84→    for _i in 1..params.iterations {
    85→        let combined = [derived.bytes.to_vec(), salt.clone()].concat();
    86→        derived = hmac_sha256(password.as_bytes(), &combined);
    87→    }
    88→
    89→    // Step 4: 요청된 길이로 트리밍
    90→    let key = derived.bytes[..params.output_length.min(32)].to_vec();
    91→
    92→    DerivedKey {
    93→        key,
    94→        salt,
    95→        iterations: params.iterations,
    96→    }
    97→}
    98→
    99→/// 결정적 키 생성 (동일한 입력 → 동일한 출력)
   100→pub fn derive_key_deterministic(
   101→    master_key: &[u8],
   102→    context: &str,  // "authentication" or "encryption"
   103→    index: u32,
   104→) -> Vec<u8> {
   105→    let input = format!("{}:key_derivation:{}:{}", context, index, bytes_to_hex(master_key));
   106→    let hash = sha256(input.as_bytes());
   107→    hash.bytes.to_vec()
   108→}
   109→
   110→/// 키 강화 (Key Stretching)
   111→/// 약한 패스워드를 강한 키로 변환
   112→pub fn stretch_key(weak_key: &[u8], stretching_factor: usize) -> Vec<u8> {
   113→    let mut result = weak_key.to_vec();
   114→
   115→    for _round in 0..stretching_factor {
   116→        let hash = sha256(&result);
   117→        result = hash.bytes.to_vec();
   118→    }
   119→
   120→    result
   121→}
   122→
   123→/// 다중 키 생성 (하나의 마스터 키에서 여러 서브 키)
   124→pub fn derive_multiple_keys(
   125→    master_key: &[u8],
   126→    count: usize,
   127→    key_length: usize,
   128→) -> Vec<Vec<u8>> {
   129→    (0..count)
   130→        .map(|i| {
   131→            let derived = derive_key_deterministic(master_key, &format!("subkey_{}", i), i as u32);
   132→            derived[..key_length.min(derived.len())].to_vec()
   133→        })
   134→        .collect()
   135→}
