     2→// NIST 표준 엔트로피 검증
     3→
     4→/// 엔트로피 분석 결과
     5→#[derive(Clone, Debug)]
     6→pub struct EntropyAnalysis {
     7→    pub entropy_bits: f64,              // 추정 엔트로피 (비트)
     8→    pub min_entropy: f64,               // 최소 엔트로피
     9→    pub is_sufficient: bool,            // NIST 128-bit 충족
    10→    pub byte_distribution: Vec<u32>,    // 각 바이트 값의 빈도
    11→    pub unique_bytes: usize,            // 고유 바이트 개수 (0-256)
    12→    pub collision_count: usize,         // 중복 바이트 개수
    13→}
    14→
    15→impl EntropyAnalysis {
    16→    pub fn meets_nist_requirement(&self) -> bool {
    17→        self.entropy_bits >= 128.0
    18→    }
    19→}
    20→
    21→/// Shannon 엔트로피 계산
    22→/// H(X) = -Σ(p_i * log2(p_i))
    23→pub fn calculate_shannon_entropy(data: &[u8]) -> f64 {
    24→    if data.is_empty() {
    25→        return 0.0;
    26→    }
    27→
    28→    let mut frequency = [0u32; 256];
    29→    for &byte in data {
    30→        frequency[byte as usize] += 1;
    31→    }
    32→
    33→    let len = data.len() as f64;
    34→    let mut entropy = 0.0;
    35→
    36→    for &count in &frequency {
    37→        if count > 0 {
    38→            let probability = count as f64 / len;
    39→            entropy -= probability * probability.log2();
    40→        }
    41→    }
    42→
    43→    entropy * data.len() as f64  // 전체 엔트로피 (비트)
    44→}
    45→
    46→/// 최소 엔트로피 (Minimum Entropy)
    47→/// -log2(max probability)
    48→pub fn calculate_min_entropy(data: &[u8]) -> f64 {
    49→    if data.is_empty() {
    50→        return 0.0;
    51→    }
    52→
    53→    let mut frequency = [0u32; 256];
    54→    for &byte in data {
    55→        frequency[byte as usize] += 1;
    56→    }
    57→
    58→    let max_count = *frequency.iter().max().unwrap() as f64;
    59→    let len = data.len() as f64;
    60→
    61→    -((max_count / len).log2()) * data.len() as f64
    62→}
    63→
    64→/// 전체 엔트로피 분석
    65→pub fn analyze_entropy(data: &[u8]) -> EntropyAnalysis {
    66→    let shannon = calculate_shannon_entropy(data);
    67→    let min_entropy = calculate_min_entropy(data);
    68→
    69→    let mut frequency = [0u32; 256];
    70→    let mut unique_bytes = 0;
    71→    let mut collision_count = 0;
    72→
    73→    for &byte in data {
    74→        frequency[byte as usize] += 1;
    75→    }
    76→
    77→    for &count in &frequency {
    78→        if count > 0 {
    79→            unique_bytes += 1;
    80→            if count > 1 {
    81→                collision_count += count - 1;
    82→            }
    83→        }
    84→    }
    85→
    86→    EntropyAnalysis {
    87→        entropy_bits: shannon,
    88→        min_entropy,
    89→        is_sufficient: shannon >= 128.0,
    90→        byte_distribution: frequency.to_vec(),
    91→        unique_bytes,
    92→        collision_count: collision_count as usize,
    93→    }
    94→}
    95→
    96→/// 바이트 분포 검증 (카이제곱 테스트 근사)
    97→pub fn validate_byte_distribution(data: &[u8]) -> f64 {
    98→    if data.len() < 256 {
    99→        return 0.0;  // 샘플이 너무 작음
   100→    }
   101→
   102→    let mut frequency = [0u32; 256];
   103→    for &byte in data {
   104→        frequency[byte as usize] += 1;
   105→    }
   106→
   107→    let expected = data.len() as f64 / 256.0;
   108→    let mut chi_square = 0.0;
   109→
   110→    for &count in &frequency {
   111→        let diff = count as f64 - expected;
   112→        chi_square += (diff * diff) / expected;
   113→    }
   114→
   115→    // χ² → p-value (근사)
   116→    // 낮은 값 = 균등 분포, 높은 값 = 불균등 분포
   117→    1.0 / (1.0 + (chi_square / 256.0))
   118→}
   119→
   120→/// Runs Test (연속성 테스트)
   121→/// 연속된 같은 바이트가 몇 개인지 확인
   122→pub fn runs_test(data: &[u8]) -> f64 {
   123→    if data.len() < 2 {
   124→        return 0.0;
   125→    }
   126→
   127→    let mut runs = 1;
   128→    for i in 1..data.len() {
   129→        if data[i] != data[i - 1] {
   130→            runs += 1;
   131→        }
   132→    }
   133→
   134→    // 이상적: runs ≈ data.len() / 2
   135→    let expected_runs = data.len() / 2;
   136→    let run_quality = (runs as f64) / (expected_runs as f64).max(1.0);
   137→
   138→    // 0.5 ~ 2.0 범위를 0.0 ~ 1.0으로 정규화
   139→    (run_quality.min(2.0) / 2.0).max(0.0)
   140→}
   141→
   142→/// 종합 엔트로피 평가
   143→pub fn comprehensive_entropy_evaluation(data: &[u8]) -> EntropyAnalysis {
   144→    let mut analysis = analyze_entropy(data);
   145→
   146→    // 추가 검증: 분포 균등성
   147→    let distribution_score = validate_byte_distribution(data);
   148→    let runs_score = runs_test(data);
   149→
   150→    // 최종 엔트로피 = Shannon × (분포 점수 + runs 점수) / 2
   151→    let adjustment_factor = (distribution_score + runs_score) / 2.0;
   152→    analysis.entropy_bits *= adjustment_factor.max(0.8);  // 최소 80%
   153→
   154→    analysis
   155→}
   156→
   157→/// 무관용 규칙: 엔트로피 >= 128 비트
   158→pub fn meets_nist_requirement(key: &[u8]) -> bool {
   159→    let analysis = analyze_entropy(key);
   160→    analysis.meets_nist_requirement()
   161→}
