     2→// 신경망 모델(template) 암호화 및 복호화
     3→
     4→use super::crypto_module::*;
     5→
     6→/// 암호화된 템플릿
     7→#[derive(Clone, Debug)]
     8→pub struct EncryptedTemplate {
     9→    pub ciphertext: Vec<u8>,         // 암호화된 데이터
    10→    pub iv: Vec<u8>,                 // Initialization Vector (16 bytes)
    11→    pub tag: Vec<u8>,                // 인증 태그 (16 bytes)
    12→    pub encrypted_key: Vec<u8>,      // 암호화된 마스터 키 (32 bytes)
    13→}
    14→
    15→impl EncryptedTemplate {
    16→    pub fn size_bytes(&self) -> usize {
    17→        self.ciphertext.len() + self.iv.len() + self.tag.len() + self.encrypted_key.len()
    18→    }
    19→}
    20→
    21→/// 평문 템플릿
    22→#[derive(Clone, Debug)]
    23→pub struct PlaintextTemplate {
    24→    pub data: Vec<u8>,
    25→}
    26→
    27→impl PlaintextTemplate {
    28→    pub fn new(data: Vec<u8>) -> Self {
    29→        PlaintextTemplate { data }
    30→    }
    31→
    32→    pub fn size_bytes(&self) -> usize {
    33→        self.data.len()
    34→    }
    35→}
    36→
    37→/// 단순 AES-like 블록 암호 (시뮬레이션)
    38→fn encrypt_block(plaintext: &[u8], key: &[u8], iv: &[u8]) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    39→    // IV 생성 (고정: 실제로는 난수)
    40→    let iv_used = if iv.is_empty() {
    41→        sha256(b"initialization_vector").bytes[..16].to_vec()
    42→    } else {
    43→        iv[..16.min(iv.len())].to_vec()
    44→    };
    45→
    46→    // 키 확장
    47→    let expanded_key = extend_key(key);
    48→
    49→    // CBC 모드 암호화
    50→    let mut ciphertext = Vec::new();
    51→    let mut prev_block = iv_used.clone();
    52→
    53→    for chunk in plaintext.chunks(16) {
    54→        let mut block = vec![0u8; 16];
    55→        for (i, &byte) in chunk.iter().enumerate() {
    56→            block[i] = byte ^ prev_block[i % 16];
    57→        }
    58→
    59→        // 단순 암호화 라운드 (16 라운드)
    60→        for _round in 0..16 {
    61→            block = encrypt_round(&block, &expanded_key);
    62→        }
    63→
    64→        ciphertext.extend_from_slice(&block);
    65→        prev_block = block;
    66→    }
    67→
    68→    // 인증 태그 생성 (GMAC-like)
    69→    let tag = generate_auth_tag(&ciphertext, &expanded_key, &iv_used);
    70→
    71→    (ciphertext, iv_used, tag)
    72→}
    73→
    74→/// 블록 암호화 라운드
    75→fn encrypt_round(block: &[u8], key: &[u8]) -> Vec<u8> {
    76→    let mut result = block.to_vec();
    77→
    78→    // SubBytes (대체)
    79→    for i in 0..16 {
    80→        result[i] = (result[i] ^ key[i % key.len()]).wrapping_mul(0x1B);
    81→    }
    82→
    83→    // ShiftRows (순환)
    84→    let temp = result.clone();
    85→    result[0] = temp[0];
    86→    result[1] = temp[5];
    87→    result[2] = temp[10];
    88→    result[3] = temp[15];
    89→    result[4] = temp[4];
    90→    result[5] = temp[9];
    91→    result[6] = temp[14];
    92→    result[7] = temp[3];
    93→    result[8] = temp[8];
    94→    result[9] = temp[13];
    95→    result[10] = temp[2];
    96→    result[11] = temp[7];
    97→    result[12] = temp[12];
    98→    result[13] = temp[1];
    99→    result[14] = temp[6];
   100→    result[15] = temp[11];
   101→
   102→    // MixColumns (섞기)
   103→    for i in (0..16).step_by(4) {
   104→        let a0 = result[i];
   105→        let a1 = result[i + 1];
   106→        let a2 = result[i + 2];
   107→        let a3 = result[i + 3];
   108→
   109→        result[i] = a0 ^ a1 ^ a2 ^ a3;
   110→        result[i + 1] = a0 ^ a1 ^ a2 ^ a3;
   111→        result[i + 2] = a0 ^ a1 ^ a2 ^ a3;
   112→        result[i + 3] = a0 ^ a1 ^ a2 ^ a3;
   113→    }
   114→
   115→    result
   116→}
   117→
   118→/// 키 확장
   119→fn extend_key(key: &[u8]) -> Vec<u8> {
   120→    let mut extended = key.to_vec();
   121→    while extended.len() < 256 {
   122→        let hash = sha256(&extended);
   123→        extended.extend_from_slice(&hash.bytes[..32.min(256 - extended.len())]);
   124→    }
   125→    extended[..256].to_vec()
   126→}
   127→
   128→/// 인증 태그 생성 (GMAC-like)
   129→fn generate_auth_tag(ciphertext: &[u8], key: &[u8], iv: &[u8]) -> Vec<u8> {
   130→    let mut input = Vec::new();
   131→    input.extend_from_slice(ciphertext);
   132→    input.extend_from_slice(iv);
   133→    input.extend_from_slice(key);
   134→
   135→    let hash = sha256(&input);
   136→    hash.bytes[..16].to_vec()
   137→}
   138→
   139→/// 단순 AES-like 블록 복호화
   140→fn decrypt_block(
   141→    ciphertext: &[u8],
   142→    key: &[u8],
   143→    iv: &[u8],
   144→    expected_tag: &[u8],
   145→) -> Result<Vec<u8>, String> {
   146→    // 인증 태그 검증
   147→    let expanded_key = extend_key(key);
   148→    let computed_tag = generate_auth_tag(ciphertext, key, iv);
   149→
   150→    if computed_tag != expected_tag {
   151→        return Err("Authentication tag mismatch - data may be tampered".to_string());
   152→    }
   153→
   154→    // CBC 모드 복호화
   155→    let mut plaintext = Vec::new();
   156→    let mut prev_block = iv.to_vec();
   157→
   158→    for chunk in ciphertext.chunks(16) {
   159→        let mut block = chunk.to_vec();
   160→
   161→        // 역 암호화 라운드
   162→        for _round in 0..16 {
   163→            block = decrypt_round(&block, &expanded_key);
   164→        }
   165→
   166→        // XOR with previous ciphertext block
   167→        for (i, &byte) in block.iter().enumerate() {
   168→            plaintext.push(byte ^ prev_block[i % prev_block.len()]);
   169→        }
   170→
   171→        prev_block = chunk.to_vec();
   172→    }
   173→
   174→    Ok(plaintext)
   175→}
   176→
   177→/// 블록 복호화 라운드
   178→fn decrypt_round(block: &[u8], key: &[u8]) -> Vec<u8> {
   179→    let mut result = block.to_vec();
   180→
   181→    // Inverse MixColumns
   182→    for i in (0..16).step_by(4) {
   183→        let a0 = result[i];
   184→        let a1 = result[i + 1];
   185→        let a2 = result[i + 2];
   186→        let a3 = result[i + 3];
   187→
   188→        result[i] = a0 ^ a1;
   189→        result[i + 1] = a1 ^ a2;
   190→        result[i + 2] = a2 ^ a3;
   191→        result[i + 3] = a3 ^ a0;
   192→    }
   193→
   194→    // Inverse ShiftRows
   195→    let temp = result.clone();
   196→    result[0] = temp[0];
   197→    result[1] = temp[13];
   198→    result[2] = temp[10];
   199→    result[3] = temp[7];
   200→    result[4] = temp[4];
   201→    result[5] = temp[1];
   202→    result[6] = temp[14];
   203→    result[7] = temp[11];
   204→    result[8] = temp[8];
   205→    result[9] = temp[5];
   206→    result[10] = temp[2];
   207→    result[11] = temp[15];
   208→    result[12] = temp[12];
   209→    result[13] = temp[9];
   210→    result[14] = temp[6];
   211→    result[15] = temp[3];
   212→
   213→    // Inverse SubBytes
   214→    for i in 0..16 {
   215→        result[i] = (result[i] ^ key[i % key.len()]).wrapping_div(0x1B);
   216→    }
   217→
   218→    result
   219→}
   220→
   221→/// 템플릿 암호화
   222→pub fn encrypt_template(
   223→    template: &PlaintextTemplate,
   224→    encryption_key: &[u8],
   225→) -> EncryptedTemplate {
   226→    let (ciphertext, iv, tag) = encrypt_block(&template.data, encryption_key, &[]);
   227→
   228→    // 마스터 키 암호화 (XOR cipher with tag)
   229→    let encrypted_key = xor_cipher(encryption_key, &tag);
   230→
   231→    EncryptedTemplate {
   232→        ciphertext,
   233→        iv,
   234→        tag,
   235→        encrypted_key,
   236→    }
   237→}
   238→
   239→/// 템플릿 복호화
   240→pub fn decrypt_template(
   241→    encrypted: &EncryptedTemplate,
   242→    decryption_key: &[u8],
   243→) -> Result<PlaintextTemplate, String> {
   244→    let plaintext = decrypt_block(
   245→        &encrypted.ciphertext,
   246→        decryption_key,
   247→        &encrypted.iv,
   248→        &encrypted.tag,
   249→    )?;
   250→
   251→    Ok(PlaintextTemplate { data: plaintext })
   252→}
   253→
   254→/// 라운드트립 검증 (암호화 → 복호화)
   255→pub fn verify_encryption_roundtrip(
   256→    template: &PlaintextTemplate,
   257→    key: &[u8],
   258→) -> Result<bool, String> {
   259→    let encrypted = encrypt_template(template, key);
   260→    let decrypted = decrypt_template(&encrypted, key)?;
   261→
   262→    Ok(decrypted.data == template.data)
   263→}
